oup {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:query {\"queryId\":1,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"\",\"inherit\":false,\"taxQuery\":null,\"parents\":[],\"format\":[]}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template -->\n<!-- wp:post-featured-image /-->\n\n<!-- wp:post-date /-->\n\n<!-- wp:post-title /-->\n<!-- /wp:post-template --></div>\n<!-- /wp:query --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></section>\n<!-- /wp:group -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"custom/custom-patterns\"],\"patternName\":\"env/text-image-columns\",\"name\":\"Text Image Columns\"},\"className\":\"cols wrapper\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group cols wrapper\"><!-- wp:group {\"className\":\"col col\\u002d\\u002dtext cols-left\"} -->\n<div class=\"wp-block-group col col--text cols-left\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><span class=\"random-letter\">/</span>o mnie.</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"cols-right\"} -->\n<div class=\"wp-block-group cols-right\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|black\"}}},\"typography\":{\"lineHeight\":\"1.2\",\"fontStyle\":\"normal\",\"fontWeight\":\"100\"}},\"textColor\":\"black\",\"fontSize\":\"1xlarge\"} -->\n<p class=\"has-black-color has-text-color has-link-color has-1-xlarge-font-size\" style=\"font-style:normal;font-weight:100;line-height:1.2\">Nazywam się <strong>Kamil </strong>i od ponad trzech lat zajmuję się tworzeniem stron internetowych, sklepów e-commerce oraz aplikacji webowych.</p>\n<!-- /wp:paragraph -->\n\n<!